package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Makes fiscal year FY<yyyy>'s twelve monthly periods, from the sheet's fiscal year start month of that
 *  year, exactly as the period generator does (a month whose name is taken or whose days overlap a period
 *  is left out). A year that is not four digits is refused and nothing is written. */
public class GenerateFiscalYear {
    public void generate(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @RequestBody GenerateFiscalYearRequest request, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods, Audit audit, Out<GeneratePeriodsResult> result) throws InvalidPeriodException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        String year = request == null || request.year() == null ? "" : request.year().trim();
        if (!year.matches("\\d{4}")) {
            throw new InvalidPeriodException("A fiscal year is four digits (yyyy)");
        }
        YearMonth start = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(id));
        sheets.open(id, user);
        result.set(new GeneratePeriodsResult(
                GeneratePeriods.months(id, user, start, start.plusMonths(11), periods, audit)));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Locks a period. Refused for anyone but a steward, and when it is already locked. */
public class LockPeriod {
    public void lock(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            RoleRepository roles, Out<Period> period) throws InvalidPeriodException, PeriodLockException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Role.STEWARD.equals(roles.roleOf(id, by == null ? "" : by))) {
            throw new PeriodLockException("Only a steward can lock a period");
        }
        if (found.locked() == true) {
            throw new PeriodLockException("The period is already locked");
        }
        period.set(periods.lock(found, true));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<ValidPeriod> body)
            throws InvalidPeriodException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPeriodException("A name is required");
        }
        if (name.length() > 200) {
            throw new InvalidPeriodException("The name is too long");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (from.isAfter(to)) {
            throw new InvalidPeriodException("The from-date must be on or before the to-date");
        }
        body.set(new ValidPeriod(name, from, to, cap(request.cap())));
    }

    private static Integer cap(String text) throws InvalidPeriodException {
        String t = text == null ? "" : text.trim();
        if (t.isEmpty()) return null;
        if (!t.matches("[0-9]{1,9}") || Integer.parseInt(t) < 1) {
            throw new InvalidPeriodException("The cap must be a whole number above zero");
        }
        return Integer.parseInt(t);
    }

    private static LocalDate date(String text) throws InvalidPeriodException {
        String t = text == null ? "" : text.trim();
        try {
            return LocalDate.parse(t);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("Not a date: " + t);
        }
    }
}
